pm.test("Validar estructura de respuesta según código HTTP recibido", function () {
    var statusCode = pm.response.code;
    var jsonData = pm.response.json();

    if (statusCode === 200) {
        pm.expect(jsonData).to.have.property('accessToken').that.is.a('string').and.is.not.empty;
        pm.expect(jsonData).to.have.property('refreshToken').that.is.a('string').and.is.not.empty;
        pm.expect(jsonData).to.have.property('id').that.is.a('number');
        pm.expect(jsonData).to.have.property('username').that.is.a('string');
        pm.expect(jsonData).to.have.property('email').that.is.a('string');
        pm.expect(jsonData).to.have.property('firstName').that.is.a('string');
        pm.expect(jsonData).to.have.property('lastName').that.is.a('string');
        pm.expect(jsonData).to.have.property('gender').that.is.a('string');
        pm.expect(jsonData).to.have.property('image').that.is.a('string');
        pm.expect(jsonData.username).to.eql('emilys');
    } else if (statusCode === 400) {
        pm.expect(jsonData).to.have.property('message');
    } else {
        pm.expect.fail('Código de respuesta inesperado: ' + statusCode + '. Se esperaba 200 o 400.');
    }
});

pm.test("Si respuesta es 200, verificar que los campos extra no se reflejan en la respuesta", function () {
    if (pm.response.code === 200) {
        var jsonData = pm.response.json();
        pm.expect(jsonData).to.not.have.property('extraField');
        pm.expect(jsonData).to.not.have.property('role');
    }
});

pm.test("Si respuesta es 400, verificar que el mensaje indica campos no reconocidos", function () {
    if (pm.response.code === 400) {
        var jsonData = pm.response.json();
        var msg = JSON.stringify(jsonData).toLowerCase();
        pm.expect(msg).to.satisfy(function(m) {
            return m.includes('extra') || m.includes('unknown') || m.includes('additional') || m.includes('invalid') || m.includes('unrecognized') || m.includes('not allowed');
        }, 'El mensaje de error debería indicar campos no reconocidos o adicionales');
    }
});

